Body:
Just in case anybody else could not get the `$SHELL` environment variable to use a batch file as in @exyi's post above:

```sh
#!/bin/bash
# file: ~/.local/bin/opencode

echo "**************************"
echo "*** RUNNING IN SANDBOX ***"
echo "**************************"

export OPENCODE_DISABLE_MODELS_FETCH=1

export SHELL="$HOME/restricted_bash"

exec bwrap \
  --unshare-pid \
  --unshare-uts \
  --unshare-ipc \
  --share-net \
  --die-with-parent \
  --new-session \
  --dev /dev \
  --ro-bind /usr /usr \
  --ro-bind /etc /etc \
  --ro-bind /lib /lib \
  --ro-bind-try /lib64 /lib64 \
  --tmpfs /run \
  --bind "$PWD" "$PWD" \
  --bind /tmp /tmp \
  --ro-bind "$HOME/.config/opencode" "$HOME/.config/opencode" \
  --bind "$HOME/.local/share/opencode" "$HOME/.local/share/opencode" \
  --bind "$HOME/.cache/opencode" "$HOME/.cache/opencode" \
  --ro-bind "$HOME/.opencode/bin/opencode" "$HOME/.opencode/bin/opencode" \
  --ro-bind "$SHELL" "$SHELL" \
  --proc /proc \
  --setenv SHELL "$SHELL" \
  --cap-drop ALL \
  -- "$HOME/.opencode/bin/opencode" "$@"
```

and just gets this error in `opencode` for all `bash` tool calls:

```
Error: ENOENT: no such file or directory, posix_spawn '/home/juk/restricted_bash'
```

---

I did manage to get it to work if I compiled a simple C program and used that:

```c
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <limits.h>
#include <sys/resource.h>

#define MAX_PROCESSES  16384
#define MAX_FILE_SIZE  (10ULL * 1024 * 1024 * 1024)  /* 10 GB */

int main(int argc, char *argv[], char *envp[]) {
    const char *home = getenv("HOME");
    const char *pwd = getenv("PWD");

    if (!home || !pwd) {
        fprintf(stderr, "HOME or PWD not set\n");
        return 1;
    }

    char config[PATH_MAX], data[PATH_MAX], cache[PATH_MAX], bin[PATH_MAX];
    snprintf(config, sizeof(config), "%s/.config/opencode", home);
    snprintf(data,   sizeof(data),   "%s/.local/share/opencode", home);
    snprintf(cache,  sizeof(cache),  "%s/.cache/opencode", home);
    snprintf(bin,    sizeof(bin),    "%s/.opencode/bin/opencode", home);

    char *prefix[] = {
        "bwrap",
        "--unshare-pid",
        "--unshare-uts",
        "--unshare-ipc",
        "--unshare-net",
        "--die-with-parent",
        "--new-session",
        "--dev", "/dev",
        "--ro-bind", "/usr", "/usr",
        "--ro-bind", "/etc", "/etc",
        "--ro-bind", "/lib", "/lib",
        "--ro-bind-try", "/lib64", "/lib64",
        "--bind", (char *)pwd, (char *)pwd,
        "--bind", "/tmp", "/tmp",
        "--ro-bind", config, config,
        "--ro-bind", data, data,
        "--ro-bind", cache, cache,
        "--ro-bind", bin, bin,
        "--proc", "/proc",
        "--", "/usr/bin/bash",
    };
    int prefix_len = sizeof(prefix) / sizeof(prefix[0]);

    int total = prefix_len + (argc - 1) + 1;
    char **args = malloc(total * sizeof(char *));

    memcpy(args, prefix, prefix_len * sizeof(char *));
    for (int i = 1; i < argc; i++)
        args[prefix_len + i - 1] = argv[i];
    args[total - 1] = NULL;

    struct rlimit nproc = { MAX_PROCESSES, MAX_PROCESSES };
    struct rlimit fsize = { MAX_FILE_SIZE, MAX_FILE_SIZE };
    setrlimit(RLIMIT_NPROC, &nproc);
    setrlimit(RLIMIT_FSIZE, &fsize);

    execve("/usr/bin/bwrap", args, envp);
    perror("execve");
    return 1;
}
```

Compiled using:

```sh
gcc restricted_bash.c -o restricted_bash
```

---

Using this 2-stage `bwrap` method and these in `opencode.json`:

```json
    "permission": {
        "external_directory": {
            "*": "deny",
            "/tmp": "allow",
            "/tmp/*": "allow"
        },
        "skill": "deny",
        "webfetch": "deny",
        "websearch": "deny",
        "bash": {
            "*": "allow",
            "sudo *": "deny",
            "su *": "deny",
            "dd *": "deny"
        }
    }
```

